class Creature {
    constructor(name, description, attackEffect) {
        this.name = name;
        this.description = description;
        this.attackEffect = attackEffect;
        this.target = null;
    }

    appear() {
        console.log(`A ${this.name} appears! ${this.description}`);
        this.triggerAttack();
    }

    triggerAttack() {
        if (this.target) {
            console.log(`${this.name} targets ${this.target}!`);
            console.log(this.attackEffect);
        } else {
            console.log(`${this.name} hovers ominously...`);
        }
    }
}

class Ghost extends Creature {
    constructor() {
        super(
            "Vengeful Spirit",
            "A shadowy figure that induces terror, a violent spirit trying to avenge a wrong done to them when they lived.",
            "The victim suddenly collapses, clutching their chest, suffering a fatal heart attack."
        );
    }
}

function randomEvent(npcs) {
    const ghost = new Ghost();

    function displayTimeToEvent(timeLeft) {
        console.log(`\`Information: Time to event: ${timeLeft} seconds\``);
    }

    const appearInterval = setInterval(() => {
        const timeToEvent = Math.floor(Math.random() * (15 - 5 + 1)) + 5; // Random interval between 5 to 15 seconds
        let countdown = timeToEvent;

        const countdownInterval = setInterval(() => {
            displayTimeToEvent(countdown);
            if (countdown <= 0) {
                clearInterval(countdownInterval);
                ghost.appear();

                // Randomly choose a target from the NPCs
                if (Math.random() < 0.5) {
                    ghost.target = npcs[Math.floor(Math.random() * npcs.length)];
                } else {
                    ghost.target = null;
                }
            }
            countdown--;
        }, 1000); // Update every second

    }, Math.floor(Math.random() * (15000 - 5000 + 1)) + 5000); // Random interval between 5 to 15 seconds

    // To stop the interval after some time (optional)
    setTimeout(() => clearInterval(appearInterval), 60000); // Stops after 60 seconds
}

// Example usage
const npcs = ["Correction Officer", "Inmate"];
randomEvent(npcs);
